/* (0.6.50) MORPH turned fast makes no click: its knob jumped 0 <-> 40 every few blocks (across the plain WAVE's render too)
 * the largest step between two samples no larger than with MORPH held (a smooth wave: a step shows) */
static int32_t morph_jump(uint32_t eng, int16_t e0, int mode)
{
    int32_t o[2u * CTL], last = 0, mx = 0;
    uint32_t b, i, k;
    track_t *t;
    ui_power_on();
    t = &trk[0];
    song.master_q12 = 4096;
    for (k = 1; k < NTRK; k++) trk[k].p[P_MUTE] = 1;
    set_engine_of(t, eng);
    t->engine = t->eng_req;
    t->p[P_E0] = e0;
    if (eng == 3u) t->p[P_E1] = 1;                       /* (LOFI: TRI) */
    t->p[P_REV] = t->p[P_DLY] = t->p[P_CHOR] = t->p[P_DIST] = 0;
    t->p[P_APDEP] = 0;
    t->p[P_MORPH] = mode == 2 ? 40 : 0;
    for (b = 0; b < 40u; b++) mix_block(o, CTL);
    trk_note_on(t, 45, 100);
    for (b = 0; b < 40u; b++) mix_block(o, CTL);
    for (b = 0; b < 120u; b++) {
        if (mode == 1) t->p[P_MORPH] = (b / 6u) & 1u ? 40 : 0;
        mix_block(o, CTL);
        for (i = 0; i < CTL; i++) {
            int32_t d = o[2u * i] - last;
            last = o[2u * i];
            if (b || i) mx = d > mx ? d : -d > mx ? -d : mx;
        }
    }
    return mx;
}
static int test_morph_click(void)
{
    int bad = 0, ok = 1;
    static const struct { uint32_t eng; int16_t e0; } C[3] = {{ENGI_ANALOG, 2}, {2u, 0}, {3u, 0}};
    uint32_t c;
    for (c = 0; c < 3u; c++) {
        int32_t a = morph_jump(C[c].eng, C[c].e0, 0), b = morph_jump(C[c].eng, C[c].e0, 2), j = morph_jump(C[c].eng, C[c].e0, 1);
        int32_t ref = a > b ? a : b;
        if (j > ref + ref / 4) {
            ok = 0;
            fprintf(stderr, "  morph click: engine %u: held %d / %d, jumped %d\n", C[c].eng, a, b, j);
        }
    }
    bad += check("MORPH turned fast (0 <-> 40): no step larger than with it held (ANALOG TRI, PHASE, LOFI TRI)", ok);
    return bad;
}
/* (0.6.51) the LFO in time (RATE below 0) and FREE (PHASE -1): in time a cycle is that many beats on the transport's
 * grid; FREE a note does not restart it; RETRIG (PHASE 0..127) as before; the display */
static int test_lfo_sync(void)
{
    int bad = 0, ok = 1;
    int32_t o[2u * CTL];
    uint32_t b, ph0, len;
    char v[12];
    const char *u;
    track_t *t;
    ui_power_on();
    t = &trk[0];
    t->p[P_LRATE] = -5;                                  /* 1/4: a cycle a beat */
    song.playing = 1;
    ms_clock = 0;
    track_lfo_tick(t);
    ph0 = t->lfo_ph;
    len = beat_samples();
    ms_clock = len / 2u;
    track_lfo_tick(t);
    ok &= ph0 < 0x01000000u && t->lfo_ph > 0x7E000000u && t->lfo_ph < 0x82000000u;   /* half a beat: half a turn */
    ms_clock = len;
    track_lfo_tick(t);
    ok &= t->lfo_ph < 0x01000000u || t->lfo_ph > 0xFF000000u;
    song.playing = 0;
    bad += check("LFO RATE 1/4 (in time): a cycle a beat on the transport's grid", ok);
    param_format(&TP[P_LRATE], -5, v, &u);
    ok = str_eq(v, "1/4");
    param_format(&TP[P_LRATE], -1, v, &u);
    ok &= str_eq(v, "4BAR");
    param_format(&TP[P_LPHASE], -1, v, &u);
    ok &= str_eq(v, "FREE");
    bad += check("LFO RATE below 0 shows the division, PHASE -1 FREE", ok);
    ui_power_on();
    t = &trk[0];
    t->p[P_LRATE] = 60;
    t->p[P_LPHASE] = -1;                                 /* FREE */
    for (b = 0; b < 10u; b++) mix_block(o, CTL);
    ph0 = t->lfo_ph;
    trk_note_on(t, 60, 100);
    ok = t->lfo_ph == ph0;
    trk_note_off(t, 60);
    for (b = 0; b < 400u; b++) mix_block(o, CTL);
    t->p[P_LPHASE] = 0;                                  /* RETRIG */
    trk_note_on(t, 62, 100);
    ok &= t->lfo_ph == 0u;
    trk_note_off(t, 62);
    bad += check("LFO PHASE FREE: a note does not restart it; 0: it does", ok);
    return bad;
}
/* (0.9.18) LFO MODE FREE never restarts the LFO: neither its phase nor its FADE, whatever plays it (keys apart or legato,
 * the sequencer, a DRUM-X kit, a rate in time); FADE fades it in once, from a project's load. TRIG (PHASE 0..127)
 * restarts both on a fresh phrase, as before. The LFO's level (lfo_val x lfo_fade) watched block by block */
static void go_title(const char *title);
static uint32_t lfo_w_jump, lfo_w_blocks;
static int32_t lfo_w_minfade;
static void lfo_watch(track_t *t, uint32_t blocks, uint32_t inc)   /* inc: the phase's step a block (0: not checked) */
{
    int32_t o[2u * CTL];
    uint32_t b, ph = t->lfo_ph;
    for (b = 0; b < blocks; b++) {
        mix_block(o, CTL);
        if (inc && t->lfo_ph - ph != inc)
            lfo_w_jump++;
        ph = t->lfo_ph;
        if (t->lfo_fade < lfo_w_minfade)
            lfo_w_minfade = t->lfo_fade;
        lfo_w_blocks++;
    }
}
static void lfo_w_reset(void) { lfo_w_jump = lfo_w_blocks = 0; lfo_w_minfade = 32767; }
static int lfo_free_case(track_t *t, int32_t fade, int seqd, int legato, const char *what)
{
    uint32_t inc = LFO_INC[t->p[P_LRATE] & 127], k;
    int ok;
    t->p[P_LPHASE] = -1;                                 /* FREE */
    t->p[P_LFADE] = (int16_t)fade;
    lfo_fade_restart((1u << NTRK) - 1u);                /* (as a project's load: FADE from 0, once) */
    lfo_w_reset();
    lfo_watch(t, 3000, inc);                             /* (FADE 100: ~2 s; the fade done) */
    ok = t->lfo_fade == 32767;
    lfo_w_reset();
    if (seqd) {
        for (k = 0; k < 16u; k += 2u)
            t->step[k] = (step_t){.note = {(uint8_t)(48 + k)}, .n = 1, .time = ST_NOTE};
        t->seq_active = 1;
        seq_start();
        lfo_watch(t, 4000, 0);                           /* (the grid moves the phase? no: a free rate) */
        transport_req = 2;
        lfo_watch(t, 4, 0);
        for (k = 0; k < NSTEP; k++)
            t->step[k] = (step_t){0};
    } else
        for (k = 0; k < 6u; k++) {
            uint32_t ph = t->lfo_ph;
            int32_t f = t->lfo_fade;
            trk_note_on(t, 60 + (int32_t)k, 100);
            ok &= t->lfo_ph == ph && t->lfo_fade == f;   /* (not even for the block: the matrix reads it before) */
            lfo_watch(t, 120, inc);
            if (legato && k)
                trk_note_off(t, 59 + (int32_t)k);        /* (the one before let go after this one began) */
            if (!legato)
                trk_note_off(t, 60 + (int32_t)k);
            lfo_watch(t, legato ? 60 : 900, inc);        /* (apart: the release over, a fresh phrase next) */
        }
    if (legato)
        trk_note_off(t, 65);
    ok &= lfo_w_minfade == 32767 && (seqd || !lfo_w_jump);
    if (!ok)
        fprintf(stderr, "  %s: %u of %u blocks jumped, the fade down to %d\n", what, lfo_w_jump, lfo_w_blocks,
                lfo_w_minfade);
    return ok;
}
static int test_lfo_free(void)
{
    int bad = 0, ok;
    uint32_t len, k;
    track_t *t;
    char v[12];
    const char *u;
    ui_power_on();
    t = &trk[0];                                         /* (ANALOG) */
    t->p[P_LRATE] = 60;
    t->p[P_LD_FLT] = 40;
    ok = lfo_free_case(t, 0, 0, 0, "FREE FADE 0, notes apart");
    ok &= lfo_free_case(t, 100, 0, 0, "FREE FADE 100, notes apart");
    ok &= lfo_free_case(t, 100, 0, 1, "FREE FADE 100, legato");
    t->p[P_VOICE] = 2;                                   /* LEGATO */
    ok &= lfo_free_case(t, 100, 0, 1, "FREE FADE 100, VOICE LEGATO");
    t->p[P_VOICE] = 1;                                   /* MONO */
    ok &= lfo_free_case(t, 100, 0, 0, "FREE FADE 100, VOICE MONO");
    t->p[P_VOICE] = 0;
    bad += check("LFO MODE FREE (free rate): no note restarts the phase or the FADE, apart or legato, POLY MONO LEGATO", ok);
    ok = lfo_free_case(t, 0, 1, 0, "FREE FADE 0, sequenced");
    ok &= lfo_free_case(t, 100, 1, 0, "FREE FADE 100, sequenced");
    bad += check("LFO MODE FREE: the sequencer's notes restart nothing either (FADE 0 and 100)", ok);
    t = &trk[3];                                         /* (DRUM-X: a hit is a fresh phrase each time) */
    t->p[P_LRATE] = 40;
    t->p[P_LD_SHP] = 40;
    ok = lfo_free_case(t, 100, 0, 0, "DRUM-X FREE FADE 100, hits");
    ok &= lfo_free_case(t, 100, 1, 0, "DRUM-X FREE FADE 100, sequenced");
    bad += check("LFO MODE FREE on a DRUM-X kit: hits restart nothing", ok);
    t = &trk[0];                                         /* TRIG: as before */
    t->p[P_LPHASE] = 32;
    t->p[P_LFADE] = 100;
    lfo_w_reset();
    lfo_watch(t, 3000, 0);
    trk_note_on(t, 60, 100);
    ok = t->lfo_ph == 32u << 25 && t->lfo_fade == 0;
    lfo_watch(t, 50, 0);
    ok &= t->lfo_fade > 0 && t->lfo_fade < 32767;
    trk_note_on(t, 64, 100);                             /* (legato: the phrase goes on) */
    ok &= t->lfo_fade > 0;
    trk_note_off(t, 60);
    trk_note_off(t, 64);
    lfo_watch(t, 900, 0);
    bad += check("LFO MODE TRIG: a fresh phrase restarts its PHASE and FADE, a legato note does not", ok);
    /* in time (RATE < 0), playing: the transport's grid, a note moves nothing (TRIG and FREE) */
    {
        uint32_t m;
        ok = 1;
        for (m = 0; m < 2u; m++) {
            t->p[P_LRATE] = -5;                          /* 1/4 */
            t->p[P_LPHASE] = m ? -1 : 0;
            t->p[P_LFADE] = 0;
            for (k = 0; k < 16u; k += 4u)
                t->step[k] = (step_t){.note = {60}, .n = 1, .time = ST_NOTE};
            t->seq_active = 1;
            seq_start();
            len = beat_samples();
            for (k = 0; k < 3000u; k++) {
                int32_t o[2u * CTL];
                uint32_t want;
                mix_block(o, CTL);
                want = (uint32_t)(((uint64_t)(ms_clock % len) << 32) / len);   /* (the tick reads ms_clock before the
                                                                                 * block's events advance it) */
                if (t->lfo_ph - want + 0x02000000u > 0x04000000u + (uint32_t)(((uint64_t)CTL << 32) / len))
                    ok = 0;
            }
            transport_req = 2;
            lfo_watch(t, 4, 0);
            for (k = 0; k < NSTEP; k++)
                t->step[k] = (step_t){0};
        }
        bad += check("LFO in time, playing: on the grid at every note (TRIG and FREE)", ok);
    }
    t->p[P_LRATE] = 60;
    /* MODE, a view of PHASE: TRIG keeps PHASE 0..127, FREE is PHASE -1 (every project before it opens as it was) */
    t->p[P_LPHASE] = 0;
    ok = lfo_mode_of(t) == 0;
    t->p[P_LPHASE] = -1;
    ok &= lfo_mode_of(t) == 1;
    param_format(&LFO_MODE_DESC, 1, v, &u);
    ok &= str_eq(v, "FREE");
    param_format(&LFO_MODE_DESC, 0, v, &u);
    ok &= str_eq(v, "TRIG");
    bad += check("LFO MODE: PHASE -1 reads FREE, 0..127 TRIG", ok);
    /* the pages: LFO = RATE WAVE MODE FADE, LFO 2 = PHASE; MODE FREE keeps TRIG's phase for TRIG again */
    ui_power_on();
    song.sel = 0;
    t = TSEL;
    t->p[P_LPHASE] = 40;
    t->p[P_LFADE] = 60;
    lfo_watch(t, 3000, 0);
    go_title("LFO"); frame();
    {
        int16_t *vp;
        const param_desc_t *d = page_desc(cur_page(), 2, &vp);
        ok = d && str_eq(d->label, "MODE") && *vp == 0;
        d = page_desc(cur_page(), 3, &vp);
        ok &= d && str_eq(d->label, "FADE");
        turn(EN_K3, 1); frame();
        ok &= t->p[P_LPHASE] == -1 && t->lfo_fade < 32767;   /* FREE: turned on, it fades in once */
        lfo_watch(t, 3000, 0);
        trk_note_on(t, 60, 100);
        ok &= t->lfo_fade == 32767;
        trk_note_off(t, 60);
        go_title("LFO MORE"); frame();                  /* (3b task 7: PHASE, JIANT's LFO 2, a row of LFO's MORE) */
        d = param_ref(t, ID_LPHS, &vp);
        ok &= d && str_eq(d->label, "PHASE") && *vp == 40;   /* (FREE: what TRIG will start from) */
        uxe_more_set(&UXM_LFO, ID_LPHS, 1); frames(200); uxe_more_set(&UXM_LFO, ID_LPHS, 1); frame();
        ok &= t->p[P_LPHASE] == -1;                      /* (PHASE in FREE: only what TRIG will start from) */
        go_title("LFO"); frame();
        turn(EN_K3, -1); frame();
        ok &= t->p[P_LPHASE] == 42;
        go_title("LFO MORE"); frame();
        uxe_more_set(&UXM_LFO, ID_LPHS, -1); frames(200); uxe_more_set(&UXM_LFO, ID_LPHS, -1); frame();
        ok &= t->p[P_LPHASE] == 40;
    }
    bad += check("LFO pages: RATE WAVE MODE FADE, MORE's PHASE (3b task 7: was LFO 2); FREE keeps TRIG's PHASE, fades in once when turned on", ok);
    /* a project: MODE kept as stored (PHASE -1 FREE, 40 TRIG at 40); its load fades the LFOs in once, a song's next
     * section (or UNDO) does not */
    t->p[P_LPHASE] = -1;
    trk[1].p[P_LPHASE] = 40;
    lfo_watch(t, 3000, 0);
    project_capture(&proj_scratch);
    ok = !project_restore_runtime(&proj_scratch) && lfo_mode_of(t) && trk[1].p[P_LPHASE] == 40 && t->lfo_fade == 0;
    lfo_watch(t, 3000, 0);
    project_capture(&proj_scratch);
    proj_lfo_keep = 1;
    ok &= !project_restore_runtime(&proj_scratch) && t->lfo_fade == 32767;
    proj_lfo_keep = 0;
    bad += check("LFO MODE in a project: as stored; a load fades FREE in once, a section / UNDO keeps it going", ok);
    {   /* LFO + SELECT: FREE half the time (was 2 in 3), TRIG at any phase 0..127 */
        uint32_t n = 0, lo = 0, hi = 0, i;
        for (i = 0; i < 4000u; i++) {
            lfo_dice(t);
            n += t->p[P_LPHASE] < 0;
            lo += t->p[P_LPHASE] >= 0 && t->p[P_LPHASE] < 64;
            hi += t->p[P_LPHASE] >= 64;
            if (t->p[P_LPHASE] < -1 || t->p[P_LPHASE] > 127) n = 99999u;
        }
        printf("ui:   LFO dice: FREE %u of 4000, TRIG 0..63 %u, 64..127 %u\n", n, lo, hi);
        bad += check("LFO dice: MODE FREE half the time, TRIG at any phase", n > 1850u && n < 2150u && lo > 850u && hi > 850u);
    }
    return bad;
}
static int test_patterns(void)
{
    int bad = 0;
    track_t *t = &trk[0], before;
    ui_power_on();
    go_page(GR_PATS);
    bad += check("SEQ > PHRASES is a SEQ page", cur_page()->fam == FAM_SEQ && str_eq(cur_page()->title, "PHRASES") &&
                 song.seq_mode);
    before = *t;
    turn(EN_K2, 1);
    bad += check("KNOB 2 loads nothing (the knobs only pick)", seq_is_empty(t) && ui.confirm == CF_NONE);
    press(B_OCTUP);                               /* LOAD 01 ACID into the empty sequencer */
    bad += check("LOAD into an empty sequencer: at once, LOADED 01 ACID", ui.confirm == CF_NONE && steps_are(t, 0) &&
                 msg_is("LOADED 01 ACID"));
    bad += check("..the sound and the track's settings untouched", same_sound(t, &before) && t->p[P_SDIV] == before.p[P_SDIV] &&
                 t->p[P_AMODE] == before.p[P_AMODE]);
    turn(EN_K1, 2);
    press(B_OCTUP);
    bad += check("a loaded pattern, untouched: the next one without asking (03 MELODY)", ui.confirm == CF_NONE && steps_are(t, 2) &&
                 msg_is("LOADED 03 MELODY"));
    t->step[3].note[0] = 70;                      /* an edit: the user's steps now */
    t->step[3].n = 1;
    t->step[3].time = ST_NOTE;
    press(B_OCTUP);
    bad += check("edited steps: the REPLACE T1 SEQUENCE? dialog", ui.confirm == CF_LOAD_PAT && ui.confirm_trk == 0u &&
                 t->step[3].note[0] == 70);
    press(B_OCTDN);
    bad += check("OCT- keeps them", ui.confirm == CF_NONE && t->step[3].note[0] == 70);
    my_steps(t);
    before = *t;
    turn(EN_K1, 9);                               /* 12 BEAT */
    press(B_OCTUP);
    press(B_OCTUP);
    bad += check("OCT+ loads (12 BEAT), no undo hint (TONIC)", ui.confirm == CF_NONE && steps_are(t, 11) &&
                 msg_is("LOADED 12 BEAT") && !ui.msg2[0]);
    /* a user preset's pattern: listed after the factory ones as U06, with its LEN DIV SWING GATE */
    my_steps(t);                                  /* (the user's steps again: no undo since TONIC) */
    t->p[P_SDIV] = 2;
    t->p[P_SSWING] = 40;
    up_store(5, "UPAT");
    t->p[P_SDIV] = 0;
    t->p[P_SSWING] = 0;
    up_store(6, "NOPAT");
    memset(up_rec(6)->note, 0, sizeof up_rec(6)->note);   /* .. a record with no pattern: not listed */
    bad += check("user presets with a pattern are listed after the factory ones", pat_count() == NPATTERNS + 1u);
    track_defaults_steps(t);
    turn(EN_K1, 20);                              /* (to the end of the list) */
    press(B_OCTUP);
    bad += check("LOAD U06: its 16 steps, LEN 16 (at most), DIV and SWING", msg_is("LOADED U06 UPAT") && t->step[0].note[0] == 40 &&
                 t->step[3].note[0] == 43 && !t->step[30].n && t->p[P_SLEN] == 16 && t->p[P_SDIV] == 2 && t->p[P_SSWING] == 40);
    /* a project's steps count as the user's */
    project_save(2);
    project_load(2);
    press(B_OCTUP);
    bad += check("over a project's steps: the dialog", ui.confirm == CF_LOAD_PAT);
    press(B_OCTDN);
    /* the hint: a load moves the pick there (3c-2 task 2: SAVE > SOUND's PRESET, the inherited PRESETS page's KNOB 1) */
    go_page(GR_SVSND);
    turn(EN_K2, 1);
    bad += check("PRESETS: a factory preset's suggested pattern becomes the pick", preset_pat_hint() >= 0 &&
                 ui.ppick == (uint8_t)preset_pat_hint());
    return bad;
}

static int test_rec(void)
{
    static const uint8_t FAMS[3] = {FAM_TRK, FAM_SEQ, FAM_ARP};
    int bad = 0;
    uint32_t k;
    for (k = 0; k < 3u; k++) {
        ui_power_on();
        track_select(2);
        open_family(FAMS[k]);
        press(B_REC);
        bad += check(k == 0 ? "REC on TRACKS: arms the selected track, PLAY starts" :
                     k == 1 ? "#133 REC on SEQ > STEP: arms the selected track for step recording, PLAY does not start" :
                     "REC on ARP: arms the selected track, PLAY starts",
                     song.rec == 4u && (k == 1u ? transport_req == 0u && msg_is("KEYS WRITE STEPS") : transport_req == 1u));
        song.playing = 1;
        transport_req = 0;
        frames(400);                                   /* (not a double tap: that locks the REC layer) */
        press(B_REC);
        bad += check("REC again disarms (the transport runs on)", song.rec == 0u && transport_req == 0u);
        frames(400);
        hold(B_REC);                                   /* 1.1.5: held, the REC layer (ui_layer.c); the arming stays */
        bad += check("REC held: its layer, closed when let go; no dialog, the arming as it was",
                     ui.confirm == CF_NONE && song.rec == 0u && !ui.layer && !transport_req);
        ui.confirm = 0;
    }
    ui_power_on();
    press(B_REC);
    bad += check("REC on HOME records without changing the screen", ui.home && song.rec == 1u && transport_req == 1u);
    /* STEP page: armed + playing -> the keys record live only */
    ui_power_on();
    open_family(FAM_SEQ);
    bad += check("SEQ opens STEP", cur_page()->scope == SC_STEP);
    press(B_REC);
    song.playing = 1;
    transport_req = 0;
    fm1_in.notes = host_notes = 1u << 7;
    frame();
    fm1_in.notes = 0;
    frame();
    bad += check("STEP, armed and playing: a key does not write the cursor step", !trk[0].step[0].n && ui.cursor == 0);
    song.rec = 0;
    fm1_in.notes = host_notes = 1u << 7;
    frame();
    fm1_in.notes = 0;
    frame();
    bad += check("#133 STEP, not armed: the key only plays (nothing written, the cursor stays)",
                 !trk[0].step[0].n && ui.cursor == 0);
    song.rec = 1;
    song.playing = 0;
    fm1_in.notes = host_notes = 1u << 7;
    frame();
    fm1_in.notes = 0;
    frame();
    bad += check("#133 STEP, armed and stopped: the key writes the cursor step (and moves on)",
                 trk[0].step[0].n == 1 && ui.cursor == 1);
    /* ARP: the arp's notes are recorded, not the key */
    ui_power_on();
    {
        track_t *t = &trk[0];
        uint32_t i, n = 0, notes = 0;
        t->engine = t->eng_req;
        t->p[P_AMODE] = 1;
        t->p[P_AOCT] = 2;
        t->p[P_APROB] = 127;
        song.rec = 1;
        song.playing = 1;
        input_on(t, 60, 100);
        for (i = 0; i < NSTEP; i++)
            n += t->step[i].n;
        bad += check("ARP on: the key held is not recorded", n == 0);
        arp_tick(t, 1);
        for (i = 0; i < NSTEP; i++)
            if (t->step[i].n)
                notes = t->step[i].note[0];
        bad += check("ARP on: the note the arp plays is recorded", notes == 60u);
        t->p[P_AMODE] = 0;
        input_off(t, 60);
    }
    return bad;
}

static uint32_t gated_notes(const track_t *t)
{
    uint32_t i, n = 0;
    for (i = 0; i < NVOICE; i++) n += t->v[i].gate != 0;
    return n;
}

static int test_midi(void)
{
    int bad = 0;
    track_t *a, *b;
    ui_power_on();
    song.sel = 2;
    midi_hint = 0;
    midi_event(0x90, 0, 60, 100); midi_event(0x90, 9, 61, 100);
    bad += check("ROUT CH1-4 (default): channel 1 -> part 1, channel 10 ignored",
                 !song.g[G_MRSEL] && mn_get(0, 60) == 1u && !mn_get(9, 61) && !gated_notes(&trk[2]));
    bad += check("a note into another track tells the UI", midi_hint == 1u);
    frame(); bad += check("MIDI IN -> T1 shown", msg_is("MIDI IN -> T1"));
    host_route_sel(1);
    midi_event(0x80, 0, 60, 0); midi_event(0x90, 0, 62, 100);
    bad += check("ROUT changes: note-off releases original owner, new note uses selection",
                 !gated_notes(&trk[0]) && mn_get(0, 62) == 3u && midi_in_mask(3) == 1u << 2);
    song.sel = 1; midi_event(0x80, 0, 62, 0);
    bad += check("note-off after selection follows the note-on's track", !mn_get(0, 62));
    midi_event(0x80, 9, 61, 0);
    ui_power_on();
    host_route_sel(1);
    midi_event(0x90, 0, 60, 100);
    song.sel = 1;
    midi_event(0x90, 0, 60, 100);
    bad += check("same MIDI channel/pitch on a new selected track releases its old owner",
                 !gated_notes(&trk[0]) && gated_notes(&trk[1]) && mn_get(0, 60) == 2u);
    midi_event(0x80, 0, 60, 0);
    midi_event(0x80, 0, 60, 0);
    bad += check("both note-offs after a MIDI ownership change leave neither track held",
                 !gated_notes(&trk[0]) && !gated_notes(&trk[1]) && !mn_get(0, 60));
    ui_power_on();
    song.sel = 2; host_route_sel(1);
    midi_event(0x90, 0, 61, 100);
    host_route_sel(0);
    midi_event(0x90, 0, 61, 100);
    midi_event(0x80, 0, 61, 0);
    bad += check("same channel/pitch across a ROUT change cannot leave its previous part held",
                 !gated_notes(&trk[2]) && !gated_notes(&trk[0]) && !mn_get(0, 61));
    {
        uint32_t hold;
        for (hold = 0; hold < 2u; hold++) {
            ui_power_on();
            host_route_sel(1);
            trk[0].p[P_AMODE] = 1; trk[0].p[P_AHOLD] = (int16_t)hold;
            midi_event(0x90, 0, 60, 100);
            song.sel = 1;
            midi_event(0x90, 0, 60, 100);
            bad += check("MIDI ownership transfer releases old ARP keys and respects explicit HOLD",
                         !trk[0].arp_phys && trk[0].nheld == hold && mn_get(0, 60) == 2u);
        }
    }
    ui_power_on();
    trk[1].p[P_AMODE] = trk[1].p[P_AHOLD] = 1;
    midi_event(0x90, 0, 60, 100);
    midi_event(0x90, 1, 64, 100);
    song.playing = 1;
    {
        uint32_t i, held = 0;
        for (i = 0; i < MQ; i++) midi_in_event(0x643C9909u);
        midi_in_event(0x003C8908u);                      /* note-off lost to a full ring */
        events_block(CTL);
        for (i = 0; i < NTRK * NVOICE; i++) held += trk[i / NVOICE].v[i % NVOICE].gate;
        bad += check("MIDI overflow releases held notes and latched ARP, keeps transport running",
                     !held && !trk[1].nheld && !trk[1].arp_phys && !mn_get(0, 60) &&
                     !mn_get(1, 64) && !midi_in_overflow && mi_r == mi_w && song.playing);
        midi_in_event(0x643D9009u);
        events_block(CTL);
        bad += check("MIDI accepts a fresh note after overflow recovery", mn_get(0, 61) == 1u && trk[0].v[0].gate);
    }
    {   /* (ACID FM 3c-1 task 7: ROUTE on no page, inert since 0.5; its descriptor kept for the projects that still hold it) */
        char v[8];
        const char *u;
        param_format(&GP[G_ROUTE], 1, v, &u);
        bad += check("ROUTE's descriptor (GLO > SYSTEM's K3 until 3c-1 task 7): CH1-4 / SEL", str_eq(GP[G_ROUTE].label, "ROUTE") &&
                     str_eq(v, "SEL"));
    }
    return bad;
}

