         uxq_t_is("RATE", seqm_val(ID_SQ_HRATE), "X1") && uxq_t_is("DIRECTION", seqm_val(ID_SQ_HDIR), "PING-PONG") &&
         uxq_t_is("INTERVAL", seqm_val(ID_SQ_HIVL), "-3 DEG");
