    uint32_t i, k;
    ux_knob_t kn[4];
    char b[48];
    ui_power_on(); frame();
    press(B_GLO); frames(320);
    ok &= str_eq(cur_page()->title, "LIVE") && uxg_owns() && ux_page_owns();
